import XCTest
@testable import SecutgCore

/// PLAN.md 3.21. `Vectors/watermark.json` is the cross-client contract (generated by Web A's
/// `tools/gen-wm-vectors.ts`); every assertion here exists so a drift in bit order, CRC, sign-magnitude, spreading
/// seed or hard-limiting shows up as a failing test rather than as a screenshot nobody can trace.
final class WatermarkTests: XCTestCase {
    let v = Vectors.load("watermark")

    private var layout: [String: Any] { return v["layout"] as! [String: Any] }
    private var geometry: [String: Any] { return v["geometry"] as! [String: Any] }
    private var projectKey: [UInt8] { return Vectors.hex(v["project_key_hex"] as! String) }

    // MARK: - Layout and geometry

    func testLayoutConstantsMatchTheContract() {
        XCTAssertEqual(WatermarkCodec.version, v["version"] as? Int)
        XCTAssertEqual(WatermarkCodec.pilotBits, layout["pilot_bits"] as? Int)
        XCTAssertEqual(WatermarkCodec.dataBits, layout["data_bits"] as? Int)
        XCTAssertEqual(WatermarkCodec.crcBits, layout["crc_bits"] as? Int)
        XCTAssertEqual(WatermarkCodec.totalBits, layout["total_bits"] as? Int)
        XCTAssertEqual(WatermarkCodec.pilotPattern.map { String($0) }.joined(), layout["pilot_pattern"] as? String)
        XCTAssertEqual(layout["field_order"] as? [String],
                       ["version:\(WatermarkCodec.versionBits)", "viewer_id:\(WatermarkCodec.viewerIdBits)",
                        "chat_id:\(WatermarkCodec.chatIdBits)", "time_bucket:\(WatermarkCodec.timeBucketBits)"])
    }

    func testGeometryConstantsMatchTheContract() {
        XCTAssertEqual(WatermarkCarrier.tile, geometry["tile_chips"] as? Int)
        XCTAssertEqual(WatermarkCodec.chips, geometry["chips_total"] as? Int)
        XCTAssertEqual(WatermarkCarrier.chipPixels, geometry["chip_px"] as? Int)
        XCTAssertEqual(WatermarkCarrier.tilePixels, geometry["tile_px"] as? Int)
        XCTAssertEqual(WatermarkCarrier.amplitude, geometry["amplitude_default"] as? Double)
        XCTAssertEqual(WatermarkPayload.bucketMinutes, geometry["bucket_minutes"] as? Int)
    }

    // MARK: - Time buckets

    func testTimeBucketsMatchTheContract() {
        for entry in v["time_buckets"] as! [[String: Any]] {
            let unix = entry["unix"] as! Int
            XCTAssertEqual(WatermarkPayload.timeBucket(nowSeconds: Int64(unix)), entry["bucket"] as? Int, "unix \(unix)")
        }
        // Floor, not truncation: a clock behind 1970 must not fold two windows onto one phase.
        XCTAssertEqual(WatermarkPayload.timeBucket(nowSeconds: -1), -1)
        XCTAssertEqual(WatermarkPayload.timeBucket(nowSeconds: -600), -1)
        XCTAssertEqual(WatermarkPayload.timeBucket(nowSeconds: -601), -2)
    }

    // MARK: - Spreading codes

    func testSpreadingCodesMatchTheContract() throws {
        for entry in v["spreading_codes"] as! [[String: Any]] {
            let index = entry["index"] as! Int
            let code = try WatermarkCodec.spreadingCode(projectKey: projectKey, index: index)
            XCTAssertEqual(code.count, WatermarkCodec.chips)
            let digest = Self.digest(code)
            XCTAssertEqual(digest.ones, entry["ones"] as? Int, "ones of code \(index)")
            XCTAssertEqual(digest.firstChips, entry["firstChips"] as? String, "first chips of code \(index)")
            XCTAssertEqual(digest.fnv1a, entry["fnv1a"] as? String, "fnv1a of code \(index)")
        }
    }

    func testSpreadingCodesAreOnePerBitAndKeyed() throws {
        let codes = try WatermarkCodec.spreadingCodes(projectKey: projectKey)
        XCTAssertEqual(codes.count, WatermarkCodec.totalBits)
        XCTAssertEqual(codes[0], try WatermarkCodec.spreadingCode(projectKey: projectKey, index: 0))
        XCTAssertNotEqual(codes[0], codes[1])
        // Without the key the pattern cannot be reproduced — that is what stands in for encrypting the payload.
        var otherKey = projectKey
        otherKey[0] ^= 1
        XCTAssertNotEqual(codes[0], try WatermarkCodec.spreadingCode(projectKey: otherKey, index: 0))
        XCTAssertThrowsError(try WatermarkCodec.spreadingCode(projectKey: [1, 2, 3], index: 0))
    }

    // MARK: - Cases: packed bits and the modulated carrier

    func testCasesMatchTheContract() throws {
        let codes = try WatermarkCodec.spreadingCodes(projectKey: projectKey)
        let cases = v["cases"] as! [[String: Any]]
        XCTAssertEqual(cases.count, 4)
        for item in cases {
            let fields = item["fields"] as! [String: Any]
            let viewerId = Int64(fields["viewer_id"] as! String)!
            let chatId = Int64(fields["chat_id"] as! String)!
            let timeBucket = fields["time_bucket"] as! Int
            let label = "viewer \(viewerId) chat \(chatId) bucket \(timeBucket)"

            let bits = try WatermarkCodec.pack(
                WatermarkCodec.Fields(viewerId: viewerId, chatId: chatId, timeBucket: timeBucket))
            XCTAssertEqual(bits.count, WatermarkCodec.totalBits, label)
            XCTAssertEqual(Self.bitsToHex(bits), item["bits_hex"] as? String, "bits of \(label)")

            let expected = item["carrier"] as! [String: Any]
            let digest = Self.digest(WatermarkCodec.modulate(bits: bits, codes: codes))
            XCTAssertEqual(digest.ones, expected["ones"] as? Int, "carrier ones of \(label)")
            XCTAssertEqual(digest.firstChips, expected["firstChips"] as? String, "carrier first chips of \(label)")
            XCTAssertEqual(digest.fnv1a, expected["fnv1a"] as? String, "carrier fnv1a of \(label)")

            // Round trip: the decoder must read back exactly what the encoder was given.
            let unpacked = try WatermarkCodec.unpack(bits)
            XCTAssertTrue(unpacked.checksumOk, label)
            XCTAssertEqual(unpacked.pilotErrors, 0, label)
            XCTAssertEqual(unpacked.version, WatermarkCodec.version, label)
            XCTAssertEqual(unpacked.viewerId, viewerId, label)
            XCTAssertEqual(unpacked.chatId, chatId, label)
            XCTAssertEqual(unpacked.timeBucket, timeBucket, label)
        }
    }

    func testCarrierConvenienceMatchesModulateOfPack() throws {
        let fields = WatermarkCodec.Fields(viewerId: 1_346_113_693, chatId: -1_001_234_567_890, timeBucket: 2_981_666)
        let expected = WatermarkCodec.modulate(bits: try WatermarkCodec.pack(fields),
                                               codes: try WatermarkCodec.spreadingCodes(projectKey: projectKey))
        XCTAssertEqual(try WatermarkCodec.carrier(projectKey: projectKey, fields: fields), expected)
    }

    // MARK: - Checksum, sign-magnitude and ranges

    func testChecksumRefusesADamagedReading() throws {
        let fields = WatermarkCodec.Fields(viewerId: 1_346_113_693, chatId: -1_001_234_567_890, timeBucket: 2_981_666)
        var bits = try WatermarkCodec.pack(fields)
        // A single flipped data bit is exactly the case that used to name an uninvolved account.
        bits[WatermarkCodec.pilotBits + WatermarkCodec.versionBits + 3] ^= 1
        let unpacked = try WatermarkCodec.unpack(bits)
        XCTAssertFalse(unpacked.checksumOk)
        XCTAssertEqual(unpacked.pilotErrors, 0)
        XCTAssertNotEqual(unpacked.viewerId, fields.viewerId)
    }

    func testPilotErrorsCountTheWrongBits() throws {
        var bits = try WatermarkCodec.pack(WatermarkCodec.Fields(viewerId: 42, chatId: -999, timeBucket: 1))
        bits[0] ^= 1
        bits[5] ^= 1
        let unpacked = try WatermarkCodec.unpack(bits)
        XCTAssertEqual(unpacked.pilotErrors, 2)
        XCTAssertTrue(unpacked.checksumOk, "the pilot is outside the checksum, so damaging it must not fail the CRC")
    }

    func testCrcIsCcittOverTheDataBitsOnly() throws {
        // The known CRC-16/CCITT (init 0xFFFF, poly 0x1021) of the ASCII "123456789", bit by bit.
        let message = Array("123456789".utf8).flatMap { byte in (0..<8).map { UInt8((byte >> (7 - $0)) & 1) } }
        XCTAssertEqual(WatermarkCodec.crc(message, from: 0, to: message.count), 0x29B1)
    }

    func testSignMagnitudeRoundTripsAndRefusesOversizedIds() throws {
        let limit = Int64(1) << 47
        for id in [Int64(0), 1, -1, 777_000, -1_001_234_567_890, limit - 1, -(limit - 1)] {
            let bits = try WatermarkCodec.pack(WatermarkCodec.Fields(viewerId: id, chatId: id, timeBucket: 7))
            let unpacked = try WatermarkCodec.unpack(bits)
            XCTAssertEqual(unpacked.viewerId, id)
            XCTAssertEqual(unpacked.chatId, id)
            XCTAssertTrue(unpacked.checksumOk)
        }
        // Refused rather than silently truncated: a wrapped id points at somebody else.
        XCTAssertThrowsError(try WatermarkCodec.pack(WatermarkCodec.Fields(viewerId: limit, chatId: 1, timeBucket: 0)))
        XCTAssertThrowsError(try WatermarkCodec.pack(WatermarkCodec.Fields(viewerId: 1, chatId: -limit, timeBucket: 0)))
        XCTAssertThrowsError(try WatermarkCodec.unpack([UInt8](repeating: 0, count: WatermarkCodec.totalBits - 1)))
    }

    // MARK: - Demodulation

    func testDemodulateReadsBackAnUndisturbedCarrier() throws {
        let codes = try WatermarkCodec.spreadingCodes(projectKey: projectKey)
        let fields = WatermarkCodec.Fields(viewerId: 1_346_113_693, chatId: -1_001_234_567_890, timeBucket: 2_981_666)
        let bits = try WatermarkCodec.pack(fields)
        let accumulator = WatermarkCodec.modulate(bits: bits, codes: codes).map { Float($0) }
        let (readBits, margins) = WatermarkCodec.demodulate(accumulator: accumulator, codes: codes)
        XCTAssertEqual(readBits, bits, "hard limiting costs ~2 dB but must not cost a bit on a clean carrier")
        XCTAssertTrue(margins.allSatisfy { $0 > 0 })
        let unpacked = try WatermarkCodec.unpack(readBits)
        XCTAssertTrue(unpacked.checksumOk)
        XCTAssertEqual(unpacked.viewerId, fields.viewerId)
        XCTAssertEqual(unpacked.chatId, fields.chatId)
    }

    // MARK: - Tile geometry

    func testChipIndexWrapsAtTheTileAndNeverGoesNegative() {
        XCTAssertEqual(WatermarkCarrier.chipIndex(0), 0)
        XCTAssertEqual(WatermarkCarrier.chipIndex(1), 0)
        XCTAssertEqual(WatermarkCarrier.chipIndex(2), 1)
        XCTAssertEqual(WatermarkCarrier.chipIndex(WatermarkCarrier.tilePixels - 1), WatermarkCarrier.tile - 1)
        XCTAssertEqual(WatermarkCarrier.chipIndex(WatermarkCarrier.tilePixels), 0)
        XCTAssertEqual(WatermarkCarrier.chipIndex(-1), WatermarkCarrier.tile - 1)
        XCTAssertEqual(WatermarkCarrier.chipIndex(-WatermarkCarrier.tilePixels), 0)
    }

    func testCarrierAtReadsTheChipThePixelFallsIn() throws {
        let carrier = try WatermarkCodec.carrier(
            projectKey: projectKey,
            fields: WatermarkCodec.Fields(viewerId: 42, chatId: -999, timeBucket: 1))
        XCTAssertEqual(WatermarkCarrier.carrierAt(carrier, x: 0, y: 0), Double(carrier[0]) * WatermarkCarrier.amplitude)
        // A 2x2 chip: all four device pixels carry the same value, which is what survives a 2x downscale.
        for (x, y) in [(0, 0), (1, 0), (0, 1), (1, 1)] {
            XCTAssertEqual(WatermarkCarrier.carrierAt(carrier, x: x, y: y), WatermarkCarrier.carrierAt(carrier, x: 0, y: 0))
        }
        // The phase repeats on the tile period and nowhere else.
        XCTAssertEqual(WatermarkCarrier.carrierAt(carrier, x: WatermarkCarrier.tilePixels, y: WatermarkCarrier.tilePixels),
                       WatermarkCarrier.carrierAt(carrier, x: 0, y: 0))
        XCTAssertEqual(WatermarkCarrier.carrierAt(carrier, x: 3, y: 0, amplitude: 4),
                       Double(carrier[1]) * 4)
    }

    func testTileImageIsBiasedSoAdditiveCompositingCanPaintIt() throws {
        let carrier = try WatermarkCodec.carrier(
            projectKey: projectKey,
            fields: WatermarkCodec.Fields(viewerId: 42, chatId: -999, timeBucket: 1))
        let size = WatermarkCarrier.tilePixels
        let rgba = WatermarkCarrier.tileRGBA(carrier)
        XCTAssertEqual(rgba.count, size * size * 4)
        for (x, y) in [(0, 0), (1, 1), (5, 9), (126, 127)] {
            let at = (y * size + x) * 4
            // 1.5 paints as 0 / 3, which averages to +1.5 — "+1.5 overall, ±1.5 around it".
            let expected: UInt8 = WatermarkCarrier.carrierAt(carrier, x: x, y: y) > 0 ? 3 : 0
            XCTAssertEqual(rgba[at], expected)
            XCTAssertEqual(rgba[at + 1], expected)
            XCTAssertEqual(rgba[at + 2], expected)
            // Opaque throughout: under additive compositing the sign must live in the colour, never in the alpha.
            XCTAssertEqual(rgba[at + 3], 255)
        }
    }

    func testFieldIsOneContinuousPhaseWhateverRegionIsDrawn() throws {
        let carrier = try WatermarkCodec.carrier(
            projectKey: projectKey,
            fields: WatermarkCodec.Fields(viewerId: 42, chatId: -999, timeBucket: 1))
        let width = 300, height = 200
        // Alpha 0 is the premultiplied-additive form the Apple renderer uses; the colour still carries the sign.
        var whole = [UInt8](repeating: 9, count: width * height * 4)
        whole.withUnsafeMutableBytes {
            WatermarkCarrier.writeField(carrier, alpha: 0, into: $0.baseAddress!, bytesPerRow: width * 4,
                                        width: width, height: height, originX: 0, originY: 0)
        }
        for (x, y) in [(0, 0), (1, 1), (7, 3), (200, 199), (299, 0)] {
            let at = (y * width + x) * 4
            let expected: UInt8 = WatermarkCarrier.carrierAt(carrier, x: x, y: y) > 0 ? WatermarkCarrier.paintedLevel() : 0
            XCTAssertEqual(whole[at], expected, "(\(x), \(y))")
            XCTAssertEqual(whole[at + 3], 0, "alpha must stay zero so source-over composites as pure addition")
        }

        // A sub-region drawn with its own origin must reproduce exactly the same pixels — the phase belongs to the
        // conversation area, never to whatever fragment happens to be redrawn.
        let offsetX = 37, offsetY = 91
        var part = [UInt8](repeating: 0, count: 64 * 48 * 4)
        part.withUnsafeMutableBytes {
            WatermarkCarrier.writeField(carrier, alpha: 0, into: $0.baseAddress!, bytesPerRow: 64 * 4,
                                        width: 64, height: 48, originX: offsetX, originY: offsetY)
        }
        for y in 0..<48 {
            for x in 0..<64 {
                XCTAssertEqual(part[(y * 64 + x) * 4], whole[((y + offsetY) * width + x + offsetX) * 4])
            }
        }
    }

    func testPaintedLevelRoundsTheEightBitOverlay() {
        XCTAssertEqual(WatermarkCarrier.paintedLevel(amplitude: 1.5), 3)
        XCTAssertEqual(WatermarkCarrier.paintedLevel(amplitude: 0.5), 1)
        XCTAssertEqual(WatermarkCarrier.paintedLevel(amplitude: 4), 8)
    }

    // MARK: - Digest helpers, mirroring `tools/gen-wm-vectors.ts`

    private static func bitsToHex(_ bits: [UInt8]) -> String {
        var out = ""
        var i = 0
        while i < bits.count {
            var nibble = 0
            for k in 0..<4 {
                nibble = (nibble << 1) | ((i + k < bits.count && bits[i + k] != 0) ? 1 : 0)
            }
            out += String(nibble, radix: 16)
            i += 4
        }
        return out
    }

    /// A carrier is 4096 signs; the digest keeps the vector file small while still pinning every chip.
    private static func digest(_ carrier: [Int8]) -> (ones: Int, firstChips: String, fnv1a: String) {
        var ones = 0
        var hash: UInt32 = 0x811c_9dc5
        for chip in carrier {
            if chip > 0 { ones += 1 }
            hash ^= chip > 0 ? 1 : 0
            hash = hash &* 0x0100_0193
        }
        var first = ""
        var i = 0
        while i < 64 {
            var nibble = 0
            for k in 0..<4 {
                nibble = (nibble << 1) | (carrier[i + k] > 0 ? 1 : 0)
            }
            first += String(nibble, radix: 16)
            i += 4
        }
        return (ones, first, String(format: "%08x", hash))
    }
}
